-- =====================================================================
-- Migration: create the urls table, its policies, and the redirect lookup
-- =====================================================================
-- This is the first migration for the Short Links database. The Supabase CLI
-- runs it once, records that it ran, and skips it after that.
--
-- Do not edit this file after it has run in a project. To change the database,
-- create a new migration with: supabase migration new <name>
-- Then write the change in that file and run: supabase db push
--
-- Applying it:
--   supabase db push
-- =====================================================================


-- ---------------------------------------------------------------------
-- 1. The urls table
-- ---------------------------------------------------------------------
-- One row in this table is one short link. "public." is the schema the app's
-- tables live in.
CREATE TABLE public.urls (

  -- id: a unique identifier for the row, such as 5f2b9c1e-....
  -- PRIMARY KEY makes it unique and the way other tables point at this row.
  -- DEFAULT gen_random_uuid() makes the database create a new id on insert,
  -- so the app never has to send one.
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),

  -- user_id: the account that owns the link.
  --   DEFAULT auth.uid() fills in the id of whoever is signed in when the row
  --   is inserted, so the browser does not have to send it.
  --   REFERENCES auth.users (id) is a foreign key. The database refuses a user_id
  --   that is not a real account in Supabase Auth.
  --   ON DELETE CASCADE deletes this user's links automatically when the account
  --   is deleted, so no links are left without an owner.
  user_id UUID NOT NULL DEFAULT auth.uid() REFERENCES auth.users (id) ON DELETE CASCADE,

  -- name: the label the user typed on the create page, such as "Workshop slides".
  --   Plain text, and optional. The app saves NULL when the box is empty.
  name TEXT,

  -- original_url: the address the short link sends visitors to.
  --   NOT NULL means every row must have a value.
  --   The CHECK uses a regular expression (~*, which ignores upper and lower case).
  --   It accepts only addresses that start with http:// or https://. The app checks
  --   this too, but the database check still applies if someone calls the API directly.
  original_url TEXT NOT NULL CHECK (original_url ~* '^https?://'),

  -- short_code: the code after /r/ in the short link, such as k3Xp9a.
  --   UNIQUE means the database refuses a second row with the same code.
  --   The app makes a random code and, if it is taken, tries another code.
  --   Only the database can guarantee that two rows never share a code, which is
  --   why the rule lives here and not only in the app.
  short_code TEXT NOT NULL UNIQUE,

  -- created_at: when the row was inserted. DEFAULT now() fills it in.
  --   The dashboard sorts by this column, newest first.
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);


-- ---------------------------------------------------------------------
-- 2. Row Level Security (RLS)
-- ---------------------------------------------------------------------
-- The browser talks to this table directly through the Supabase API. RLS is the
-- check that runs on every query, in the database itself, so no user can read or
-- change another user's links by calling the API with a different request.
--
-- Once RLS is on, a query is allowed only when a policy below says so. A table
-- with RLS on and no policies returns no rows at all. That is the safe default.
ALTER TABLE public.urls ENABLE ROW LEVEL SECURITY;

-- Read policy: a signed-in user can read only the rows they own.
--   FOR SELECT applies to reads.
--   TO authenticated limits it to signed-in users. Anonymous visitors are not
--   covered, so they cannot read this table. The redirect lookup in section 3
--   is the only anonymous access.
--   USING (user_id = auth.uid()) keeps only the rows whose owner is the current user.
CREATE POLICY "Users can read their own links"
  ON public.urls FOR SELECT
  TO authenticated
  USING (user_id = auth.uid());

-- Insert policy: a signed-in user can add rows only for themselves.
--   FOR INSERT applies to new rows.
--   WITH CHECK is the rule a new row must pass. The check stops a user from
--   inserting a row with someone else's user_id, even by sending it on purpose.
CREATE POLICY "Users can create their own links"
  ON public.urls FOR INSERT
  TO authenticated
  WITH CHECK (user_id = auth.uid());

-- Delete policy: a signed-in user can delete only the rows they own.
--   FOR DELETE applies to deletes. Rows owned by someone else are not matched,
--   so the database removes nothing and does not report an error.
CREATE POLICY "Users can delete their own links"
  ON public.urls FOR DELETE
  TO authenticated
  USING (user_id = auth.uid());


-- ---------------------------------------------------------------------
-- 3. The public redirect lookup
-- ---------------------------------------------------------------------
-- When someone opens /r/k3Xp9a, the redirect page needs the destination for
-- that code. The visitor is not signed in, and the RLS rules above would hide
-- the row, so the page cannot read the table directly.
--
-- This function is the one narrow door. It returns only the original_url for a
-- code. It does not return user_id, name, or created_at, so visitors learn the
-- destination and nothing about the owner.
CREATE FUNCTION public.get_original_url(code TEXT)

-- RETURNS TEXT: the function gives back a single text value, or NULL when no row matches.
RETURNS TEXT

-- LANGUAGE SQL: the body is a plain SQL query. No procedural code is needed.
LANGUAGE SQL

-- STABLE: the function reads data but never changes it. The database can use
-- this to plan queries better.
STABLE

-- SECURITY DEFINER: the function runs with the rights of its owner (the person
-- who ran the migration), not the rights of the visitor calling it. That is what
-- lets it read a row that the RLS policies hide from anonymous visitors.
-- Only this one column is returned, so the wider access is kept small.
SECURITY DEFINER

-- SET search_path: decides which schema names the function looks up.
-- A SECURITY DEFINER function that does not set this could be tricked into
-- using a table with the same name in another schema. Pinning it to public closes that gap.
SET search_path = public

AS $$
  -- The query: find the row whose short_code matches the code the caller passed
  -- in, and return its original_url. If there is no match, the result is NULL.
  SELECT original_url FROM public.urls WHERE short_code = code;
$$;

-- Functions can be run by any role by default. These two lines remove that default
-- and give access only to the roles that need it.
--   REVOKE ... FROM PUBLIC removes the default for all roles.
--   GRANT ... TO anon, authenticated lets anonymous visitors (the redirect page
--   before sign-in) and signed-in users call the function. Nobody else can.
REVOKE EXECUTE ON FUNCTION public.get_original_url(TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_original_url(TEXT) TO anon, authenticated;
